mapper.select:
select csd.ID,csd.SD_NAME,csd.CATEGORY_ID,csd.DORMITORY_ID,dor.DORMITORY_NAME,csd.PARK_ID, park.PARK_NAME,csd.ROOM_LIST from SMT_COMMON_SD csd left join SMT_PARK park on csd.PARK_ID=park.ID left join SMT_DORMITORY dor on csd.DORMITORY_ID=dor.ID where csd.STATUS=1
and csd.CATEGORY_ID=#{categoryId}
and csd.PARK_ID in
#{item}
order by csd.ID asc

select csd.ID,csd.SD_NAME,csd.CATEGORY_ID,csd.DORMITORY_ID,dor.DORMITORY_NAME,csd.PARK_ID,
park.PARK_NAME,csd.ROOM_LIST
from SMT_COMMON_SD csd
inner join SMT_COMMON_SD_METERREAD csmd on csd.ID=csmd.COMMON_ID
left join SMT_PARK park on csd.PARK_ID=park.ID
left join SMT_DORMITORY dor on csd.DORMITORY_ID=dor.ID
where csd.STATUS=1

	and csd.PARK_ID=#{parkId}


	and csd.DORMITORY_ID=#{dormitoryId}


	and csd.CATEGORY_ID=#{categoryId}


	and csmd.METER_MONTH=#{meterMonth}


	and csd.PARK_ID in

		#{item}


order by csd.ID asc
